// Given: the debug-draw palette. Do not edit this file.
// Light and dark variants are picked from the page's colour scheme.
import type { PrimColor } from "../trace/trace";

const light = {
  background: "#fbfbf9",
  grid: "#ebeae4",
  axis: "#d2d0c6",
  ink: "#26251f",
  muted: "#8a887e",
  a: "#2563c9",
  b: "#c2410c",
  normal: "#0f8a5f",
  contact: "#c0266d",
  highlight: "#b7791f",
  dynamic: "#26251f",
  static: "#8a887e",
};

const dark: typeof light = {
  background: "#17171a",
  grid: "#232328",
  axis: "#34343b",
  ink: "#e8e6df",
  muted: "#8c8a83",
  a: "#6ea0f5",
  b: "#f08a54",
  normal: "#45c495",
  contact: "#ef6aa6",
  highlight: "#e6b04a",
  dynamic: "#e8e6df",
  static: "#8c8a83",
};

export type Palette = typeof light;

export function palette(): Palette {
  const prefersDark =
    typeof window !== "undefined" && window.matchMedia?.("(prefers-color-scheme: dark)").matches;
  return prefersDark ? dark : light;
}

/** Resolves a primitive's colour: a palette name, or any CSS colour as is. */
export function resolveColor(c: PrimColor | undefined, p: Palette): string {
  if (c === undefined) return p.ink;
  return c in p ? p[c as keyof Palette] : c;
}
